#!/usr/bin/env bash
# RT-003 patch-provenance checks (automated, runnable without the full product):
#
#   1. The tracked unified patch, applied to a fresh copy of the pinned NAM
#      sources, reproduces the configure-time generated overlay byte-for-byte.
#   2. Overlay generation is idempotent: two fresh configures of the same pinned
#      source yield identical generated bytes.
#   3. A mutated pinned source fails closed (SHA256 guard aborts configure).
#
# Exits non-zero if any check fails.
set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
NAM_CORE_DIR=""
OVERLAY_DIR=""
PATCH_FILE=""
CMAKE_BIN="cmake"
SOURCE_DIR=""
WORKDIR=""

while [ $# -gt 0 ]; do
    case "$1" in
        --nam-core-dir) NAM_CORE_DIR="$2"; shift 2 ;;
        --overlay-dir)  OVERLAY_DIR="$2";  shift 2 ;;
        --patch)        PATCH_FILE="$2";   shift 2 ;;
        --cmake)        CMAKE_BIN="$2";    shift 2 ;;
        --source-dir)   SOURCE_DIR="$2";   shift 2 ;;
        --workdir)      WORKDIR="$2";      shift 2 ;;
        *) echo "unknown arg $1" >&2; exit 64 ;;
    esac
done

for v in NAM_CORE_DIR OVERLAY_DIR PATCH_FILE SOURCE_DIR WORKDIR; do
    if [ -z "${!v}" ]; then echo "missing --${v}" >&2; exit 64; fi
done

fail=0
note() { echo "  $*"; }
ok()   { echo "PASS  $*"; }
bad()  { echo "FAIL  $*"; fail=$((fail + 1)); }

rm -rf "$WORKDIR"
mkdir -p "$WORKDIR"

echo "RT-003 patch checks"
echo "  nam core : $NAM_CORE_DIR"
echo "  overlay  : $OVERLAY_DIR"
echo "  patch    : $PATCH_FILE"

# --- 1. tracked patch reproduces the overlay ---------------------------------
PT="$WORKDIR/patchtree"
mkdir -p "$PT/NAM"
cp "$NAM_CORE_DIR/NAM/lstm.cpp" "$NAM_CORE_DIR/NAM/lstm.h" "$PT/NAM/"
if (cd "$PT" && patch -p1 --silent < "$PATCH_FILE"); then
    if cmp -s "$PT/NAM/lstm.cpp" "$OVERLAY_DIR/lstm.cpp" \
       && cmp -s "$PT/NAM/lstm.h" "$OVERLAY_DIR/lstm.h"; then
        ok "tracked patch reproduces generated overlay byte-for-byte"
    else
        bad "tracked patch output differs from generated overlay"
        diff -u "$PT/NAM/lstm.cpp" "$OVERLAY_DIR/lstm.cpp" || true
        diff -u "$PT/NAM/lstm.h" "$OVERLAY_DIR/lstm.h" || true
    fi
else
    bad "tracked patch did not apply cleanly to pinned sources"
fi

# --- helper: tiny configure-only project -------------------------------------
make_proj() {
    local dir="$1"
    mkdir -p "$dir"
    cat > "$dir/CMakeLists.txt" <<EOF
cmake_minimum_required(VERSION 3.22)
project(namrt_probe NONE)
include("${SOURCE_DIR}/../../cmake/nam-rt/NamRtPatch.cmake")
nam_rt_generate_overlay("${2}")
EOF
}

# --- 2. idempotence -----------------------------------------------------------
IDEM="$WORKDIR/idem"
make_proj "$WORKDIR/idem-src" "$NAM_CORE_DIR"
"$CMAKE_BIN" -S "$WORKDIR/idem-src" -B "$WORKDIR/idem-b1" > "$WORKDIR/idem-b1.log" 2>&1
GEN1="$WORKDIR/idem-b1/nam-rt/generated/NAM"
"$CMAKE_BIN" -S "$WORKDIR/idem-src" -B "$WORKDIR/idem-b2" > "$WORKDIR/idem-b2.log" 2>&1
GEN2="$WORKDIR/idem-b2/nam-rt/generated/NAM"
if cmp -s "$GEN1/lstm.cpp" "$GEN2/lstm.cpp" && cmp -s "$GEN1/lstm.h" "$GEN2/lstm.h"; then
    ok "overlay generation idempotent across two fresh configures"
else
    bad "overlay generation not idempotent"
fi
if cmp -s "$GEN1/lstm.cpp" "$OVERLAY_DIR/lstm.cpp" && cmp -s "$GEN1/lstm.h" "$OVERLAY_DIR/lstm.h"; then
    ok "fresh generation equals the built overlay"
else
    bad "fresh generation differs from the built overlay"
fi

# --- 3. stale/mutated source fails closed ------------------------------------
MUT="$WORKDIR/mutated"
mkdir -p "$MUT/NAM"
cp "$NAM_CORE_DIR/NAM/lstm.cpp" "$MUT/NAM/lstm.cpp"
cp "$NAM_CORE_DIR/NAM/lstm.h" "$MUT/NAM/lstm.h"
# one-byte change in the pinned bytes must trip the SHA guard
printf '// rt003 staleness probe\n' >> "$MUT/NAM/lstm.cpp"
make_proj "$WORKDIR/mut-src" "$MUT"
set +e
"$CMAKE_BIN" -S "$WORKDIR/mut-src" -B "$WORKDIR/mut-b" > "$WORKDIR/mut.log" 2>&1
mut_rc=$?
set -e
if [ "$mut_rc" -ne 0 ] && grep -q "SHA256 mismatch" "$WORKDIR/mut.log"; then
    ok "mutated pinned source fails closed with SHA256 mismatch"
else
    bad "mutated pinned source did not fail closed (rc=$mut_rc)"
    tail -20 "$WORKDIR/mut.log" || true
fi

echo
if [ "$fail" -eq 0 ]; then
    echo "ALL RT-003 PATCH CHECKS PASSED"
    exit 0
fi
echo "$fail RT-003 PATCH CHECK(S) FAILED"
exit 1
